@CrossOrigin
@RestController
@RequestMapping("/ApplicationQuery")
public class ApplicationQueryRestController extends BaseSpringRestController {
	
	public ApplicationQueryRestController( ApplicationService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Application using a UUID
     * @param		UUID applicationId
     * @return		Application
     */    
    @GetMapping("/load")
    public Application load( @RequestParam(required=true) UUID applicationId ) {
    	Application entity = null;

    	try {  
    		entity = service.getApplication( new ApplicationFetchOneSummary( applicationId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Application using Id " + applicationId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Application business objects
     * @return		Set<Application>
     */
    @GetMapping("/")
    public List<Application> loadAll() {                
    	List<Application> applicationList = null;
        
    	try {
            // load the Application
            applicationList = service.getAllApplication();
            
            if ( applicationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Applications" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Applications ", exc );
        	return null;
        }

        return applicationList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Application application = null;
    protected ApplicationService service = null;
    private static final Logger LOGGER = Logger.getLogger(ApplicationQueryRestController.class.getName());
    
}
